package com.yeyamo_mobile.api.referral_service.infrastructure.messaging;
import java.util.UUID;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.referral_service.application.ReferralApplicationService;
@Component public class ReferralEventConsumer{
 private final ObjectMapper mapper;private final ReferralApplicationService service;private final ProcessedEventRepository processed;public ReferralEventConsumer(ObjectMapper m,ReferralApplicationService s,ProcessedEventRepository p){mapper=m;service=s;processed=p;}
 @KafkaListener(topics={"${yeyamo.kafka.topics.user-events:user.events}","${yeyamo.kafka.topics.legacy-user-events:user-events}","${yeyamo.kafka.topics.mission-events:mission.events}"},groupId="${spring.kafka.consumer.group-id:referral-service}")@Transactional
 public void consume(String raw)throws Exception{JsonNode event=mapper.readTree(raw);UUID id=UUID.fromString(required(event,"eventId"));if(processed.existsById(id))return;if(event.path("eventVersion").asInt(0)!=1)throw new IllegalArgumentException("Unsupported event version");String type=required(event,"eventType");JsonNode payload=event.path("payload");String correlation=text(event,"correlationId");switch(type){case"user.created","profile.created"->{String email=text(payload,"email");if(email!=null&&!email.isBlank())service.onUserCreated(id,first(payload,"userId","authUserId"),email,correlation);}case"mission.completed"->service.onMissionCompleted(id,required(payload,"userId"),correlation);default->{}}processed.save(new ProcessedEventEntity(id,type));}
 private String first(JsonNode n,String...fields){for(String field:fields){String value=text(n,field);if(value!=null&&!value.isBlank())return value;}throw new IllegalArgumentException("User id is required");}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}
}
